import {careers,lessons,companies,sources} from './content.js';
import {projectGrowth,budgetSummary,matchCareers,validSymbol} from './finance.js';
import {courses} from './courses.js';
const portfolioItems=['US stocks','International stocks','Bonds','Cash'];
import {lessonCore} from './lessonCore.js';
import {careerTeaching} from './careerTeaching.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M16 8l-3 5-5 3 3-5z',chart:'M4 3v17h17 M7 14l4-5 4 3 5-7',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',wallet:'M3 6h17v14H3z M3 6l14-3v3 M15 11h6v5h-6z',book:'M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-7-2-10 1v15',arrow:'M4 12h15 M14 7l5 5-5 5',up:'M6 18 18 6 M6 6h12v12',building:'M4 21V7l8-4 8 4v14 M2 21h20 M8 9v2 M12 9v2 M16 9v2 M8 14v2 M12 14v2 M16 14v2',people:'M9 4a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M3 20v-3a6 6 0 0 1 12 0v3 M17 4a3 3 0 0 1 0 6 M18 13a5 5 0 0 1 3 5v2',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12l9 3 9-3 M10 13h4',code:'M8 5 2 12l6 7 M16 5l6 7-6 7 M14 3l-4 18',document:'M5 2h10l4 4v16H5z M14 2v5h5 M8 11h8 M8 15h8 M8 19h5',layers:'m2 7 10-5 10 5-10 5z M2 12l10 5 10-5 M2 17l10 5 10-5',coins:'M12 3c-5 0-9 2-9 4s4 4 9 4 9-2 9-4-4-4-9-4 M3 7v10c0 2 4 4 9 4s9-2 9-4V7 M3 12c0 2 4 4 9 4s9-2 9-4',globe:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M2 12h20 M12 2c-6 6-6 14 0 20 6-6 6-14 0-20',check:'M5 12l4 4L19 6',calendar:'M3 5h18v16H3z M3 10h18 M7 2v6 M17 2v6',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const arrow=icon('arrow');
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
let storageOk=true, state={completed:[],watch:[],notes:{},careerSaved:[],courseDone:{}};
try{const saved=JSON.parse(localStorage.getItem('finance-campus-v1')||'null');if(saved&&typeof saved==='object'){for(const key of ['completed','watch','careerSaved'])if(Array.isArray(saved[key]))state[key]=saved[key].filter(v=>typeof v==='string');if(saved.notes&&typeof saved.notes==='object'&&!Array.isArray(saved.notes))state.notes=saved.notes;if(saved.courseDone&&typeof saved.courseDone==='object'&&!Array.isArray(saved.courseDone))state.courseDone=saved.courseDone}}catch{storageOk=false}
const save=()=>{try{localStorage.setItem('finance-campus-v1',JSON.stringify(state))}catch{storageOk=false;toast('This browser cannot save progress. Your current session still works.')}};
let page='overview',careerFilter='All paths',lessonFilter='All lessons',stockFilter='All sectors',compare=new Set(),personalTab='start',activeSymbol='NASDAQ:AAPL',selectedMarket='AMEX:SPY',toastTimer;
const marketCatalog=[{label:'S&P 500 · SPY ETF proxy',symbol:'AMEX:SPY',group:'Large U.S. companies'},{label:'Dow Jones Industrial Average · DIA ETF proxy',symbol:'AMEX:DIA',group:'Large U.S. companies'},{label:'Nasdaq-100 · QQQ ETF proxy',symbol:'NASDAQ:QQQ',group:'Technology-heavy indexes'},{label:'Nasdaq Composite · ONEQ ETF proxy',symbol:'NASDAQ:ONEQ',group:'Technology-heavy indexes'},{label:'Russell 2000 · IWM ETF proxy',symbol:'AMEX:IWM',group:'Company size indexes'},{label:'S&P MidCap 400 · MDY ETF proxy',symbol:'AMEX:MDY',group:'Company size indexes'},{label:'S&P SmallCap 600 · IJR ETF proxy',symbol:'AMEX:IJR',group:'Company size indexes'},{label:'Total U.S. stock market · VTI ETF',symbol:'AMEX:VTI',group:'Broad market'}];
const titles={overview:'Overview',careers:'Career explorer',markets:'Market pulse',stocks:'Stock research',personal:'Personal finance',learn:'Learning library',progress:'My progress',sources:'Sources & data'};
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000)}
function sourceLinks(keys){return `<div class="sources">${keys.map(k=>`<a href="${sources[k][1]}" target="_blank" rel="noopener noreferrer">${sources[k][0]} ↗</a>`).join('')}</div>`}
function heading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function modal(title,html){$('#modal-eyebrow').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal()}
function go(name){if(!(name in titles))name='overview';if(location.hash.slice(1)!==name)location.hash=name;else render()}
function nav(){const options=[['overview','home','Overview'],['careers','compass','Career explorer'],['markets','chart','Market pulse'],['stocks','search','Stock research'],['personal','wallet','Personal finance'],['learn','book','Learning library']];$('#nav').innerHTML=options.map(([id,i,t])=>`<button data-page="${id}" title="${t}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('');$('#page-label').textContent=titles[page]}
function careerCard(c,compact=false){return `<article class="career-card"><div class="card-top"><span class="icon-box ${c.color}">${icon(c.icon)}</span><span class="pill ${c.color}">${c.tag}</span></div><h3>${c.name}</h3><p>${c.summary}</p><div class="card-foot"><button class="text-button" data-career="${c.id}">Explore path ${arrow}</button>${compact?'<span class="small-note">Career crash course</span>':`<label class="compare-check"><input type="checkbox" data-compare="${c.id}" ${compare.has(c.id)?'checked':''}> Compare</label>`}</div></article>`}
function lessonCard(l){const done=state.completed.includes(l.id);return `<article class="lesson-card ${done?'completed':''}"><span class="icon-box ${l.track==='Personal finance'?'orange':l.track==='Stock research'?'blue':''}">${icon(l.icon)}</span><span class="pill">${l.track}</span><h3>${l.title}</h3><p>${l.summary}</p><div class="lesson-meta"><span>${done?'<span class="done">✓ Completed</span>':`${l.minutes} min · Lesson + practice`}</span><button class="text-button" data-lesson="${l.id}">${done?'Review':'Start lesson'} ${arrow}</button></div></article>`}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 440 245"><g stroke="#35505a" stroke-width=".7"><path d="M25 70h395M25 110h395M25 150h395M25 190h395M80 25v190M145 25v190M210 25v190M275 25v190M340 25v190M405 25v190"/><circle cx="375" cy="45" r="100" fill="none"/><circle cx="375" cy="45" r="78" fill="none"/></g><g transform="translate(43 30)"><rect x="25" y="108" width="45" height="65" rx="5" fill="#628b89"/><rect x="93" y="80" width="45" height="93" rx="5" fill="#88a6a0"/><rect x="161" y="50" width="45" height="123" rx="5" fill="#c3c9b8"/><rect x="229" y="12" width="45" height="161" rx="5" fill="#e4b38c"/><path d="M30 98 105 67 173 35 259-3" stroke="#edc295" stroke-width="2" fill="none"/><path d="m244-7 18 2-5 17" stroke="#edc295" stroke-width="2" fill="none"/></g><g transform="translate(25 28)"><rect width="121" height="40" rx="7" fill="#f8faf5"/><circle cx="20" cy="20" r="11" fill="#e0ebe3"/><path d="m15 20 4 4 7-8" fill="none" stroke="#497b62" stroke-width="1.5"/><text x="39" y="18" fill="#344b4f" font-size="9" font-family="Arial">YOUR BEST ASSET?</text><text x="39" y="30" fill="#6e8387" font-size="9" font-family="Arial">What you know.</text></g><text x="282" y="229" font-family="Arial" font-size="8" letter-spacing="1.5" fill="#9cb2b6">LEARN. EXPLORE. GROW.</text></svg></div>`}
function overview(){const next=lessons.find(l=>!state.completed.includes(l.id))||lessons[0],progress=Math.round(state.completed.length/lessons.length*100);return heading('Your future starts here.','Explore your path. Understand the markets. Make your next move.',`<span class="date">${icon('calendar')}${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span>`)+`<section class="hero"><div class="hero-text"><span class="eyebrow">BEYOND THE CLASSROOM</span><h2>Build your knowledge.<br>Find your place in finance.</h2><p>From your first investment to your future career —<br>let’s connect what you learn to what comes next.</p><button class="primary" data-page="careers">Explore career paths ${arrow}</button></div>${heroArt()}</section><div class="stats"><div class="stat"><span class="icon-box blue">${icon('compass')}</span><div><strong>8</strong><span>Career paths to explore</span></div></div><div class="stat"><span class="icon-box orange">${icon('book')}</span><div><strong>${state.completed.length}<small> / 10</small></strong><span>Lessons completed</span></div></div><div class="stat"><span class="icon-box purple">${icon('star')}</span><div><strong>${state.watch.length}</strong><span>On your watchlist</span></div></div></div><div class="columns"><section><div class="section-head"><h2>${state.completed.length?'Keep your momentum':'Start with the essentials'}</h2><button class="text-button" data-page="learn">All lessons ${arrow}</button></div><div class="panel"><div class="learning-feature"><div class="lesson-art">${icon(next.icon)}</div><div><span class="pill">${next.track.toUpperCase()}</span><h3>${next.title}</h3><p>${next.summary}</p><button class="primary" data-lesson="${next.id}">${progress===100?'Revisit a lesson':'Start learning'} ${arrow}</button></div></div><div class="progress-line"><span style="width:${progress}%"></span></div><div class="progress-caption"><span>Your learning journey</span><span>${state.completed.length} of 10 lessons complete</span></div><div class="next-lessons"><span>${icon('book')} Small lessons. Lasting confidence.</span><button class="text-button" data-page="progress">My progress ${arrow}</button></div></div></section><aside><div class="section-head"><h2>A little financial fluency</h2></div><div class="panel term-card"><span class="eyebrow">CONCEPT SPOTLIGHT</span><h3>Opportunity cost</h3><p>The value of the next-best alternative you give up when you make a choice.</p><div class="term-example">An hour spent researching a stock is also an hour you could spend building a skill. Time is capital, too.</div><button class="text-button" data-page="personal" style="margin-top:18px">Put a concept into practice ${arrow}</button></div></aside></div><section><div class="section-head"><div><h2>There’s more than one way into finance.</h2><p>Get to know the work behind the job title.</p></div><button class="text-button" data-page="careers">View all paths ${arrow}</button></div><div class="career-grid">${[careers[0],careers[1],careers[3]].map(c=>careerCard(c,true)).join('')}</div></section><div class="bottom-banner"><span class="icon-box">${icon('globe')}</span><div class="banner-copy"><strong>Connect the classroom to the market.</strong><p>Explore charts, headlines and the questions behind the numbers.</p></div><button class="secondary" data-page="markets">Visit market pulse ${arrow}</button></div>`}
function careerPage(){return heading('Find the work that fits you.','Go beyond the job title. Compare the work, the skills and the tradeoffs.',`<button class="secondary" id="match-open">Find a starting point ${icon('compass')}</button>`)+`<div class="toolbar"><div class="tabs">${['All paths','Investing','Deals','People','Business','Risk & data'].map(f=>`<button data-career-filter="${f}" class="${careerFilter===f?'active':''}">${f}</button>`).join('')}</div></div><div class="career-grid full">${careers.filter(c=>careerFilter==='All paths'||c.tag===careerFilter).map(c=>careerCard(c)).join('')}</div><p class="small-note">Role descriptions are a starting point. Responsibilities, recruiting timelines and credentials vary by employer. Every path includes a three-part course, interview practice and example employers. Employer lists are starting points, not live vacancies.</p><div id="compare-bar"></div>`}
function compareBar(){const el=$('#compare-bar');if(el)el.innerHTML=compare.size?`<div class="compare-bar"><p>${compare.size} of 3 paths selected</p><button class="primary" id="compare-open" ${compare.size<2?'disabled':''}>Compare side by side ${arrow}</button></div>`:''}
function lessonPage(){const progress=state.completed.length;return heading('From first principles to finance fluency.','Ten guided crash-course units build from zero knowledge to introductory college-level analysis.')+`<div class="learning-bar"><span class="icon-box orange">${icon('book')}</span><div class="progress-group"><strong>${progress} of 10 guided lessons completed</strong><div class="progress-line"><span style="width:${progress*10}%"></span></div><p class="small-note">Each unit teaches the concepts before its check-for-understanding quiz. Work through the sequence for a beginner-to-college-level foundation.</p></div><button class="text-button" data-page="progress">My progress ${arrow}</button></div><div class="toolbar"><div class="tabs">${['All lessons','Investing essentials','Stock research','Personal finance','Markets'].map(t=>`<button class="${lessonFilter===t?'active':''}" data-lesson-filter="${t}">${t}</button>`).join('')}</div></div><div class="lesson-grid">${lessons.filter(l=>lessonFilter==='All lessons'||l.track===lessonFilter).map(lessonCard).join('')}</div>`}
function marketsPage(){const groups=[...new Set(marketCatalog.map(x=>x.group))];return heading('Read the market. Build your perspective.','Follow a simple price line for the broad market and major U.S. indexes.',`<button class="secondary" id="refresh-markets">Reload market widgets ↻</button>`)+`<div class="notice">A simple line chart is embedded on this page. Choose a market below to see its price over time. ETF choices track the named index or the broad U.S. market; the ETF price can differ slightly from the index. Data is provided by TradingView and may be delayed.</div><section class="panel market-live-panel"><div class="market-toolbar"><div><span class="eyebrow">LIVE INTERACTIVE CHART</span><h2 id="market-selected-title">${marketCatalog.find(x=>x.symbol===selectedMarket)?.label||'S&P 500 · SPY ETF proxy'}</h2></div><label class="market-select-label" for="market-select">Choose a market<select id="market-select" aria-label="Choose a market to chart">${groups.map(g=>`<optgroup label="${g}">${marketCatalog.filter(x=>x.group===g).map(x=>`<option value="${x.symbol}" ${x.symbol===selectedMarket?'selected':''}>${x.label}</option>`).join('')}</optgroup>`).join('')}</select></label></div><div class="widget-shell market-chart-shell"><div id="market-chart" class="widget-mount"></div></div><div class="market-chart-caption"><span>Use the chart’s date-range controls to zoom in or out.</span><a class="provider-link" href="https://www.tradingview.com/markets/" target="_blank" rel="noopener noreferrer">Chart data by TradingView ↗</a></div></section><div class="market-grid"><section><div class="section-head"><h2>Headlines to explore</h2><span class="pill">PROVIDER FEED</span></div><div class="widget-shell"><div id="market-news" class="widget-mount"></div><a class="provider-link" href="https://www.tradingview.com/news/" target="_blank" rel="noopener noreferrer">Read the latest news on TradingView ↗</a></div></section><section class="panel"><h2>What are you seeing?</h2><p>Start by naming the selected index or fund, the date range, and whether you are reading a point move or percentage move. Then ask how the index is weighted and whether the move is broad.</p><button class="text-button" data-lesson="macro">Learn how to read markets ${arrow}</button></section></div>${marketGuide()}<div class="panel"><div class="section-head"><h2>Don’t just read the headline.</h2><button class="text-button" data-lesson="macro">Learn the framework ${arrow}</button></div><div class="three-questions"><p><strong>01 · What changed?</strong> Separate the new data from the commentary.</p><p><strong>02 · Compared with what?</strong> Look at expectations, the prior period and revisions.</p><p><strong>03 · Who is affected?</strong> Consider revenue, costs, borrowing and valuation.</p></div></div><div class="source-cards"><a href="https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm" target="_blank" rel="noopener noreferrer">Federal Reserve calendar ↗<p>Policy decisions, meeting minutes and upcoming meetings.</p></a><a href="https://www.bls.gov/schedule/news_release/" target="_blank" rel="noopener noreferrer">Economic release calendar ↗<p>Official employment, inflation and other BLS releases.</p></a><a href="https://www.sec.gov/edgar/search/" target="_blank" rel="noopener noreferrer">Go straight to the filings ↗<p>Read company disclosures at the original source.</p></a></div>`}
function widget(id,type,config){const el=document.getElementById(id);if(!el)return;el.replaceChildren();const container=document.createElement('div');container.className='tradingview-widget-container';container.style.width='100%';container.style.height='100%';const mount=document.createElement('div');mount.className='tradingview-widget-container__widget';mount.style.width='100%';mount.style.height='calc(100% - 32px)';container.append(mount);const script=document.createElement('script');script.src=`https://s3.tradingview.com/external-embedding/embed-widget-${type}.js`;script.async=true;script.textContent=JSON.stringify({colorTheme:'light',isTransparent:true,locale:'en',width:'100%',...config});script.onerror=()=>{if(el.isConnected)el.innerHTML='<div class="empty"><h3>Market data could not load.</h3><p>Check your connection or use the TradingView link below.</p></div>'};container.append(script);el.append(container)}
function loadMarkets(){const chosen=marketCatalog.find(x=>x.symbol===selectedMarket)||marketCatalog[0];widget('market-chart','symbol-overview',{symbols:[[chosen.label,`${chosen.symbol}|1D`]],height:480,chartOnly:false,chartType:'area',changeMode:'price-and-percent',valuesTracking:'1',showVolume:false,showMA:false,hideDateRanges:false,dateRanges:['1m|1D','3m|1D','12m|1D','60m|1W'],lineWidth:2});widget('market-news','timeline',{feedMode:'market',market:'stock',height:420,displayMode:'regular'})}
function stockRow(c){const symbol=c.symbol, saved=state.watch.includes(symbol);return `<div class="stock-row"><span class="ticker-mark">${esc(symbol.split(':')[1].slice(0,4))}</span><div class="stock-copy"><strong>${esc(c.name||symbol)}</strong><small>${esc(c.sector||'Saved symbol')} · ${esc(symbol)}</small></div><button class="text-button" data-stock="${esc(symbol)}">Research ${arrow}</button><button class="star-button ${saved?'saved':''}" data-watch="${esc(symbol)}" aria-label="${saved?'Remove':'Add'} ${esc(c.name||symbol)} ${saved?'from':'to'} watchlist" aria-pressed="${saved}">${saved?'★':'☆'}</button></div>`}
function stocksPage(){return heading('Think like an analyst.','Discover companies, investigate the business and build a research watchlist.')+`<div class="notice">These are educational research starting points, not buy recommendations or a ranked stock screen. Market quotes and fundamentals load from TradingView when you open a company.</div><div class="stock-layout"><section class="panel"><div class="section-head"><h2>Companies to study</h2><span class="pill blue">RESEARCH IDEAS</span></div><div class="toolbar"><input id="stock-search" class="search-field" placeholder="Search company or ticker" aria-label="Search companies"><select id="stock-sector" aria-label="Filter sector">${['All sectors',...new Set(companies.map(c=>c.sector))].map(s=>`<option ${stockFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><div id="company-list">${companies.filter(c=>stockFilter==='All sectors'||c.sector===stockFilter).map(stockRow).join('')}</div></section><section><div class="panel"><div class="section-head"><h2>Your watchlist</h2><span class="pill orange">${state.watch.length} SAVED</span></div><div id="watch-list">${state.watch.length?state.watch.map(s=>stockRow(companies.find(c=>c.symbol===s)||{symbol:s,name:s})).join(''):'<p class="watch-empty">Tap a star to save a company. Start with a business you want to understand.</p>'}</div></div><div class="panel" style="margin-top:20px"><h2>Look up another company</h2><p class="small-note">Use an exchange and ticker, such as NASDAQ:AAPL or NYSE:JPM.</p><form id="symbol-form" class="research-header"><input name="symbol" aria-label="Exchange and ticker" placeholder="EXCHANGE:TICKER" required maxlength="40"><button class="primary">Research ${arrow}</button></form><p id="symbol-error" class="form-status error" role="status"></p></div><div class="panel" style="margin-top:20px"><span class="eyebrow">THE RESEARCH HABIT</span><h3>Build a thesis you can challenge.</h3><p class="small-note">What does the business do? Why might it grow? What is already in the price? What could go wrong?</p><button class="text-button" data-lesson="thesis">Learn the research framework ${arrow}</button></div></section></div>`}
function personalPage(){let body='';if(personalTab==='start')body=`<div class="columns"><div class="panel"><span class="eyebrow">START WHERE YOU ARE</span><h2>Build a foundation before a portfolio.</h2><p class="lead">Understand your cash flow, make room for unexpected costs, and separate near-term needs from long-term goals.</p><div class="activity-row"><span class="icon-box orange">${icon('wallet')}</span><div><strong>Know your monthly numbers</strong><small>Map income, essentials and savings.</small></div><button class="text-button" data-personal="budget">Try it ${arrow}</button></div><div class="activity-row"><span class="icon-box">${icon('shield')}</span><div><strong>Plan for the unexpected</strong><small>Start with a savings buffer you can build.</small></div><button class="text-button" data-lesson="budget">Learn ${arrow}</button></div></div><div class="panel term-card"><span class="eyebrow">A USEFUL DISTINCTION</span><h3>The account is<br>the container.</h3><p>The stock, bond or fund is what you hold inside it. The investment you own is separate from the account that holds it.</p><button class="text-button" data-lesson="account">Learn how it works ${arrow}</button></div></div><div class="lesson-grid">${lessons.filter(l=>l.track==='Personal finance').map(lessonCard).join('')}</div>`;
if(personalTab==='growth')body=`<div class="panel"><div class="section-head"><div><h2>Give time a job.</h2><p>Explore a hypothetical compound-growth scenario.</p></div><button class="text-button" data-lesson="compound">Learn the concept ${arrow}</button></div><div class="calc-grid"><form id="growth-form" class="calc-fields"><label>Starting amount ($)<input name="initial" type="number" min="0" max="100000000" value="1000" required></label><label>Monthly contribution ($)<input name="monthly" type="number" min="0" max="1000000" value="100" required></label><label>Time horizon (years)<input name="years" type="number" min="1" max="60" value="10" required></label><label>Assumed annual return (%)<input name="rate" type="number" min="-50" max="50" step="0.1" value="5" required></label><button class="primary">Update projection ${arrow}</button></form><div id="growth-result" aria-live="polite"></div></div><p class="small-note">Illustration only. Assumes a constant effective annual return, equivalent monthly compounding, and contributions at each month’s end. Excludes taxes, fees and inflation. Real returns vary and can be negative.</p></div>`;
if(personalTab==='budget')body=`<div class="panel"><div class="section-head"><div><h2>Make room for what matters.</h2><p>A monthly practice budget. Use sample amounts or your own estimates.</p></div></div><div class="calc-grid"><form id="budget-form" class="calc-fields">${[['income','Take-home income / support',1800],['essentials','Essentials',950],['flexible','Flexible spending',250],['debt','Debt payments',150],['savings','Planned savings',200]].map(([n,l,v])=>`<label>${l} ($)<input type="number" name="${n}" min="0" max="100000000" value="${v}" required></label>`).join('')}<button class="primary">Review budget ${arrow}</button></form><div id="budget-result" aria-live="polite"></div></div><p class="small-note">These calculator amounts are not saved. Include a monthly allowance for irregular costs such as books or travel.</p></div>`;
if(personalTab==='portfolio')body=portfolioPage();
return heading('Your money. A more confident start.','Practical tools and U.S. investing lessons for life beyond the classroom.')+`<div class="tabs personal-tabs">${[['start','Start here'],['growth','Growth calculator'],['budget','Budget lab'],['portfolio','Portfolio lab']].map(([id,label])=>`<button data-personal="${id}" class="${personalTab===id?'active':''}">${label}</button>`).join('')}</div>${body}`}
function progressPage(){const done=lessons.filter(l=>state.completed.includes(l.id)),saved=careers.filter(c=>state.careerSaved.includes(c.id));return heading('Look how far you’ve come.','Your lessons, saved paths and research notes — all in one place.')+`<div class="notice">Progress and notes are stored in this browser only. They do not sync between devices. Clearing browser storage removes them.${storageOk?'':' Storage is currently unavailable; changes may not persist.'}</div><div class="two-grid"><section class="panel"><h2>Learning progress · ${done.length}/10</h2><div class="progress-line"><span style="width:${done.length*10}%"></span></div>${done.length?done.map(l=>`<div class="activity-row"><span class="icon-box">${icon('check')}</span><div><strong>${l.title}</strong><small>${l.track}</small></div><button class="text-button" data-lesson="${l.id}">Review ${arrow}</button></div>`).join(''):'<p class="small-note">Complete a lesson quiz to record your first milestone.</p><button class="primary" data-page="learn">Start learning '+arrow+'</button>'}</section><section class="panel"><h2>Saved career paths</h2>${saved.length?saved.map(c=>`<div class="activity-row"><span class="icon-box ${c.color}">${icon(c.icon)}</span><div><strong>${c.name}</strong><small>${c.tag}</small></div><button class="text-button" data-career="${c.id}">Explore ${arrow}</button></div>`).join(''):'<p class="small-note">Open a career guide and save a path that interests you.</p><button class="secondary" data-page="careers">Explore paths '+arrow+'</button>'}</section></div><h2 class="subheading">Your research notebook</h2><div class="saved-notes">${Object.entries(state.notes).filter(([s,n])=>validSymbol(s)&&n&&typeof n==='object').map(([s,n])=>`<article class="note-card"><div class="section-head"><h3>${esc(s)}</h3><button class="text-button" data-stock="${esc(s)}">Continue research ${arrow}</button></div><p>${esc(n.thesis||'No thesis written yet.')}</p><p class="small-note">Last saved: ${esc(n.date||'Unknown')}</p></article>`).join('')||'<div class="empty"><h3>Your ideas deserve a notebook.</h3><p>Research a company, write down a thesis and save it here.</p><button class="secondary" data-page="stocks">Find a company '+arrow+'</button></div>'}</div>`}
function sourcesPage(){return heading('Know where the information comes from.','Primary sources for learning. Provider data for markets.')+`<div class="panel"><h2>About this workspace</h2><p class="lead">Finance Campus is an educational app for U.S. college students. Lessons and role summaries were prepared on October 9, 2026. They are not automatically updated; follow the primary sources for current tax rules, requirements and disclosures.</p><p class="lead">Charts, company fundamentals and news are embedded from TradingView. Availability and data delays vary by exchange and provider. They require an internet connection and may be blocked by browser settings. The app does not manufacture fallback quotes or execute trades.</p><p class="lead">Lesson progress, saved career paths, watchlists and notes stay in your browser’s local storage. No account credentials, API keys or brokerage connections are needed. Third-party widgets and Google Fonts make external network requests.</p></div><h2 class="subheading">The source library</h2><div class="sources-list">${Object.values(sources).map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('')}<a href="https://www.tradingview.com/widget-docs/" target="_blank" rel="noopener noreferrer">TradingView · Data widgets ↗</a></div>`}
function render(){page=location.hash.slice(1)||'overview';if(!(page in titles))page='overview';nav();$('#main').innerHTML=({overview,careers:careerPage,learn:lessonPage,markets:marketsPage,stocks:stocksPage,personal:personalPage,progress:progressPage,sources:sourcesPage}[page])();document.title=`${titles[page]} · Finance Campus`;if(page==='careers')compareBar();if(page==='markets')loadMarkets();if(page==='personal'&&personalTab==='growth')updateGrowth();if(page==='personal'&&personalTab==='budget')updateBudget();if(page==='personal'&&personalTab==='portfolio')updatePortfolio();}
function openCareer(id){const c=careers.find(c=>c.id===id);if(!c)return;modal('CAREER FIELD GUIDE',`<h2>${c.name}</h2><p class="lead">${c.mission}</p><div class="tags">${c.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><div class="detail-grid"><div><h3>A day in the work</h3><p>${c.day}</p><h3>What you produce</h3><p>${c.output}</p></div><div><h3>A possible starting path</h3><p>${c.entry}</p><h3>The tradeoff</h3><p>${c.tradeoff}</p></div></div><div class="quiz"><span class="eyebrow">TRY THE WORK BEFORE THE TITLE</span><h3>Your practice assignment</h3><p>${c.exercise}</p></div>${sourceLinks(c.sources)}<button class="primary" data-save-career="${c.id}">${state.careerSaved.includes(c.id)?'✓ Saved — remove path':'Save this career path'}</button>`)}
function openLesson(id){const l=lessons.find(l=>l.id===id);if(!l)return;modal(`${l.track.toUpperCase()} · ${l.minutes} MIN`, `<h2>${l.title}</h2><p class="lead">${l.summary}</p>${l.body.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}${(lessonCore[l.id]||[]).map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}${sourceLinks(l.sources)}<form class="quiz" id="quiz-form" data-id="${l.id}"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h3>${l.question}</h3>${l.options.map((o,i)=>`<label><input type="radio" name="answer" value="${i}" required> ${o}</label>`).join('')}<button class="primary">Check answer ${arrow}</button><p id="quiz-feedback" class="form-status" role="status"></p></form>`)}
function showCompare(){const list=careers.filter(c=>compare.has(c.id));modal('CAREER COMPARISON',`<h2>Different work. Different strengths.</h2><div class="table-wrap"><table class="account-table"><thead><tr><th>Compare</th>${list.map(c=>`<th>${c.name}</th>`).join('')}</tr></thead><tbody>${[['Mission','mission'],['Typical work','day'],['Deliverable','output'],['Starting path','entry'],['Tradeoff','tradeoff'],['Try it','exercise']].map(([label,key])=>`<tr><th>${label}</th>${list.map(c=>`<td>${c[key]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small-note">Illustrative role patterns; specific positions vary. Use the career guides’ sources and current job descriptions to investigate further.</p>`)}
function matchModal(){modal('CAREER EXPLORATION',`<h2>What kind of work draws you in?</h2><p>Choose what sounds interesting. We’ll suggest three paths to investigate. This is a transparent interest match, not an aptitude test.</p><form id="fit-form" class="fit-form"><label>I want to understand…<select name="interest"><option value="markets">Markets and businesses as investments</option><option value="deals">Company transactions and financing</option><option value="people">People and their financial goals</option><option value="business">How a business plans and operates</option><option value="risk">What could go wrong</option></select></label><label>I would enjoy more…<select name="work"><option value="research">Reading, researching and writing</option><option value="team">Team projects and business decisions</option><option value="conversation">Listening and client conversations</option><option value="data">Coding, statistics and data</option></select></label><label>I’d like my work to support…<select name="purpose"><option value="investing">Investment decisions</option><option value="advising">Advice and recommendations</option><option value="planning">A plan and its execution</option></select></label><button class="primary">Show starting points ${arrow}</button></form><div id="fit-results"></div>`)}
function openStock(symbol){if(!validSymbol(symbol))return;activeSymbol=symbol;const c=companies.find(c=>c.symbol===symbol),n=state.notes[symbol]||{};modal('COMPANY RESEARCH',`<h2>${esc(c?.name||symbol)}</h2><p class="small-note">${esc(symbol)}${c?' · '+c.sector:''}. Research example, not a recommendation.</p><div class="button-row"><button class="secondary" data-watch="${esc(symbol)}">${state.watch.includes(symbol)?'★ Remove from watchlist':'☆ Add to watchlist'}</button><a class="secondary" href="https://www.sec.gov/edgar/search/" target="_blank" rel="noopener noreferrer">Search SEC filings ↗</a></div>${c?`<p class="notice"><strong>Questions to investigate:</strong> ${c.focus}.</p>`:''}<div class="widget-shell"><div id="stock-chart" class="widget-mount"></div><a class="provider-link" href="https://www.tradingview.com/symbols/${encodeURIComponent(symbol.replace(':','-'))}/" target="_blank" rel="noopener noreferrer">Open this symbol on TradingView ↗</a></div><p class="small-note">Provider data may be delayed or unavailable. Check the timestamp and reporting period. Unsupported symbols will not show a quote.</p><h3 class="fundamental-title">Dig into the fundamentals</h3><div class="widget-shell"><div id="stock-financials" class="widget-mount"></div><a class="provider-link" href="https://www.tradingview.com/" target="_blank" rel="noopener noreferrer">Financial data by TradingView ↗</a></div><form id="notebook-form" class="notebook" data-symbol="${esc(symbol)}"><h3>Your research notebook</h3><label for="thesis">My thesis — how does it make money, and what might change?</label><textarea id="thesis" name="thesis" rows="3" maxlength="4000" placeholder="Separate facts from assumptions…">${esc(n.thesis||'')}</textarea><label for="risks">Risks — what could prove me wrong?</label><textarea id="risks" name="risks" rows="3" maxlength="4000" placeholder="Competition, valuation, debt, execution…">${esc(n.risks||'')}</textarea><label for="evidence">Evidence — sources, reporting dates and next questions</label><textarea id="evidence" name="evidence" rows="3" maxlength="4000" placeholder="Paste public source links and note the reporting period…">${esc(n.evidence||'')}</textarea><p class="small-note">Saved on this browser. Do not include account numbers or other sensitive information.</p><button class="primary">Save research notes ${icon('check')}</button><p id="notes-status" class="form-status" role="status"></p></form>`);widget('stock-chart','symbol-overview',{symbols:[[symbol+'|1D']],height:320,chartOnly:false,showVolume:true,showMA:false});widget('stock-financials','financials',{symbol,height:370,displayMode:'regular'})}
function updateGrowth(){const form=$('#growth-form');if(!form||!form.reportValidity())return;const f=new FormData(form);try{const result=projectGrowth(...['initial','monthly','years','rate'].map(k=>Number(f.get(k))));const max=Math.max(...result.series.flatMap(p=>[p.balance,p.contributed]),1);const pts=key=>result.series.map((p,i)=>`${40+i/(result.series.length-1)*480},${170-p[key]/max*150}`).join(' ');$('#growth-result').innerHTML=`<span class="calc-caption">HYPOTHETICAL ENDING BALANCE</span><div class="calc-number">${money(result.balance)}</div><div class="calc-values"><div><strong>${money(result.contributed)}</strong><span>Your contributions</span></div><div><strong>${money(result.growth)}</strong><span>Hypothetical gain / loss</span></div></div><svg class="chart" viewBox="0 0 550 200" role="img" aria-label="Hypothetical balance and contributions over ${f.get('years')} years"><path d="M40 20v150h480" stroke="#dce3e8" fill="none"/><path d="M40 70h480M40 120h480" stroke="#eef1f3"/><polyline points="${pts('contributed')}" stroke="#abc0cb" stroke-width="3" fill="none"/><polyline points="${pts('balance')}" stroke="#d96040" stroke-width="3" fill="none"/><text x="40" y="190">Today</text><text x="470" y="190">Year ${esc(f.get('years'))}</text></svg><div class="legend"><span>Hypothetical balance</span><span>Contributions</span></div>`}catch(e){$('#growth-result').textContent=e.message}}
function updateBudget(){const form=$('#budget-form');if(!form||!form.reportValidity())return;const f=new FormData(form);try{const r=budgetSummary(...['income','essentials','flexible','debt','savings'].map(k=>Number(f.get(k))));$('#budget-result').innerHTML=`<div class="budget-result ${r.remaining<0?'negative':''}"><span class="calc-caption">${r.remaining<0?'MONTHLY SHORTFALL':'LEFT TO ALLOCATE'}</span><div class="calc-number">${money(Math.abs(r.remaining))}</div><p class="small-note">${r.remaining<0?'Your planned outflows exceed income. Revisit the amounts, timing or income assumptions.':r.remaining===0?'Every dollar has a planned purpose. Revisit the plan when your circumstances change.':'This is the amount left after the spending, debt payments and savings you entered.'}</p><div class="calc-values"><div><strong>${money(r.spent)}</strong><span>Spending + debt</span></div><div><strong>${r.savingsRate.toFixed(1)}%</strong><span>Planned savings / income</span></div></div></div><div class="notice">Include minimum debt payments and near-term needs in your planning. These amounts are a practice exercise, not a personalized spending prescription.</div>`}catch(e){$('#budget-result').textContent=e.message}}
function searchModal(){modal('SEARCH YOUR CAMPUS',`<h2>What would you like to understand?</h2><input id="global-search" class="wide" type="search" placeholder="Try “Roth”, “risk”, or “asset management”…" aria-label="Search lessons and careers"><div id="search-results" class="search-results"></div>`);$('#global-search').focus();searchContent('')}
function searchContent(query){query=query.toLowerCase().trim();const a=lessons.filter(l=>`${l.title} ${l.summary} ${l.track} ${l.body.flat().join(' ')}`.toLowerCase().includes(query)).map(l=>({title:l.title,sub:l.track+' · Lesson',attr:'lesson',id:l.id}));const b=careers.filter(c=>`${c.name} ${c.summary} ${c.skills}`.toLowerCase().includes(query)).map(c=>({title:c.name,sub:'Career field guide',attr:'career',id:c.id}));$('#search-results').innerHTML=[...a,...b].slice(0,10).map(r=>`<button class="search-result" data-${r.attr}="${r.id}"><strong>${r.title}</strong><small>${r.sub}</small></button>`).join('')||'<p>No results yet. Try a broader finance term.</p>'}
function toggleWatch(symbol){if(!validSymbol(symbol))return;if(state.watch.includes(symbol))state.watch=state.watch.filter(s=>s!==symbol);else state.watch.push(symbol);save();if(page==='stocks')render();if($('#modal').open){const b=$(`[data-watch="${symbol}"]`,$('#modal'));if(b)b.textContent=state.watch.includes(symbol)?'★ Remove from watchlist':'☆ Add to watchlist'}toast(state.watch.includes(symbol)?'Added to your research watchlist.':'Removed from your watchlist.')}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const b=e.target.closest('button');if(!b)return;if(b.dataset.page){$('#modal').close();go(b.dataset.page)}if(b.dataset.career)renderCareerCourse(b.dataset.career);if(b.dataset.lesson)openLesson(b.dataset.lesson);if(b.dataset.careerFilter){careerFilter=b.dataset.careerFilter;render()}if(b.dataset.lessonFilter){lessonFilter=b.dataset.lessonFilter;render()}if(b.dataset.personal){personalTab=b.dataset.personal;if(page==='personal')render();else go('personal')}if(b.dataset.watch)toggleWatch(b.dataset.watch);if(b.dataset.stock)openStock(b.dataset.stock);if(b.dataset.saveCareer){const id=b.dataset.saveCareer;state.careerSaved=state.careerSaved.includes(id)?state.careerSaved.filter(x=>x!==id):[...state.careerSaved,id];save();b.textContent=state.careerSaved.includes(id)?'✓ Saved — remove path':'Save this career path';if(page==='progress')render()}if(b.id==='compare-open')showCompare();if(b.id==='match-open')matchModal();if(b.id==='search-open')searchModal();if(b.id==='modal-close')$('#modal').close();if(b.id==='refresh-markets'){loadMarkets();toast('Market widgets reloaded. Check provider timestamps.')}});
document.addEventListener('change',e=>{if(e.target.dataset.compare){const id=e.target.dataset.compare;if(e.target.checked&&compare.size>=3){e.target.checked=false;toast('Compare up to three paths at a time.');return}e.target.checked?compare.add(id):compare.delete(id);compareBar()}if(e.target.id==='stock-sector'){stockFilter=e.target.value;filterCompanies()}if(e.target.id==='market-select'){selectedMarket=e.target.value;const title=$('#market-selected-title');if(title)title.textContent=marketCatalog.find(x=>x.symbol===selectedMarket)?.label||selectedMarket;loadMarkets()}});
function filterCompanies(){const q=($('#stock-search')?.value||'').toLowerCase();const list=companies.filter(c=>(stockFilter==='All sectors'||c.sector===stockFilter)&&`${c.name} ${c.symbol}`.toLowerCase().includes(q));$('#company-list').innerHTML=list.map(stockRow).join('')||'<p class="watch-empty">No matching company in this learning set. Use the exchange:ticker lookup for another company.</p>'}
document.addEventListener('input',e=>{if(e.target.id==='stock-search')filterCompanies();if(e.target.id==='global-search')searchContent(e.target.value)});
document.addEventListener('submit',e=>{const form=e.target;if(!['quiz-form','fit-form','notebook-form','symbol-form','growth-form','budget-form'].includes(form.id))return;e.preventDefault();const data=new FormData(form);if(form.id==='quiz-form'){const l=lessons.find(l=>l.id===form.dataset.id),correct=Number(data.get('answer'))===l.answer;const feedback=$('#quiz-feedback');feedback.classList.toggle('error',!correct);feedback.textContent=correct?'Correct. '+l.explain+' Lesson complete.':'Not quite. '+l.explain+' Try again.';if(correct){state.completed=[...new Set([...state.completed,l.id])];save();render()}}if(form.id==='fit-form'){const matches=matchCareers(careers,[...data.values()]);$('#fit-results').innerHTML='<h3>Three paths to investigate</h3>'+matches.map(c=>`<div class="match-result"><strong>${c.name}</strong><p>${c.score} of 3 interest tags matched. ${c.summary}</p><button class="text-button" data-career="${c.id}">Explore the work ${arrow}</button></div>`).join('')+'<p class="small-note">Matches count shared interest tags. Ties follow the guide order; they are not a ranking of ability or career outcomes.</p>'}if(form.id==='notebook-form'){const symbol=form.dataset.symbol;state.notes[symbol]={thesis:String(data.get('thesis')),risks:String(data.get('risks')),evidence:String(data.get('evidence')),date:new Date().toLocaleString('en-US')};save();$('#notes-status').textContent=storageOk?'Research notes saved on this browser.':'Notes are in memory; browser storage is unavailable.';if(page==='progress')render()}if(form.id==='symbol-form'){const s=String(data.get('symbol')).trim().toUpperCase();if(!validSymbol(s))$('#symbol-error').textContent='Enter an exchange and ticker, such as NASDAQ:AAPL.';else openStock(s)}if(form.id==='growth-form')updateGrowth();if(form.id==='budget-form')updateBudget()});
$('#search-open').innerHTML=icon('search');window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();

function careerTabButton(id,label,active){return `<button class="${active===id?'active':''}" data-career-tab="${id}">${label}</button>`}
function renderCareerCourse(id,tab='course'){
 const c=careers.find(x=>x.id===id),course=courses[id];if(!c||!course)return;
 const done=state.courseDone[id]||[],modules=[...course.modules.map(([title,teaching,practice])=>[title,teaching,'',practice]),...(careerTeaching[id]||[])];
 let content='';
 if(tab==='course')content=`<p class="notice">This guided course starts with the basics and builds toward college-level analysis. Open each lesson, study the concept, apply it, then mark it complete. Each path includes technical practice and professional judgment.</p>${modules.map(([title,teaching,details,practice],i)=>`<details class="course-module"><summary><strong>${esc(title)}</strong><span>${done.includes(String(i))?'✓ Complete':'Open lesson'}</span></summary><p>${esc(teaching)}</p><p>${esc(details||'')}</p><div class="practice-prompt"><strong>Apply what you learned</strong><p>${esc(practice)}</p></div><button class="secondary" data-course-done="${id}:${i}">${done.includes(String(i))?'Mark incomplete':'Mark lesson complete'}</button></details>`).join('')}<p class="small-note">${done.length} of ${modules.length} lessons marked complete in this browser.</p>`;
 if(tab==='interview')content=`<h3>Interview practice</h3><p>Try answering out loud in two minutes. Structure each answer as context → analysis → conclusion → limitation. For behavioral questions, describe your own contribution and what you learned.</p>${course.interview.map((q,i)=>`<details class="course-module"><summary><strong>${i===2?'Practice exercise':`Question ${i+1}`}</strong></summary><p>${esc(q)}</p><p class="small-note">A strong response is specific, explains assumptions and acknowledges uncertainty.</p></details>`).join('')}<h3>Preparation plan</h3><ol class="lesson-list"><li>Read the job description and map its required skills to a class, project or work example.</li><li>Review the employer’s business, products and latest public information.</li><li>Practice concise answers, prepare thoughtful questions and test your interview setup.</li><li>Afterward, write down what you learned and one skill to strengthen.</li></ol>`;
 if(tab==='employers')content=`<p>These are examples of organizations with relevant teams, not a list of current openings or a promise that they hire for every role. Search each official careers page for current roles, location and recruiting dates.</p>${course.employers.map(([group,...orgs])=>`<h3>${esc(group)}</h3><div class="employer-grid">${orgs.map(([name,url])=>`<a class="employer-link" href="${url}" target="_blank" rel="noopener noreferrer">${esc(name)} careers ↗</a>`).join('')}</div>`).join('')}<h3>How to explore an employer</h3><p>Compare the team’s responsibilities, entry-level role titles, skills named in postings, location and application timing. Verify requirements on the employer’s own site.</p>`;
 modal('CAREER FIELD GUIDE',`<h2>${esc(c.name)}: learn the work</h2><p class="lead">${esc(c.mission)}</p><div class="tags">${c.skills.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><div class="detail-grid"><div><h3>A day in the work</h3><p>${esc(c.day)}</p><h3>What you produce</h3><p>${esc(c.output)}</p></div><div><h3>A possible starting path</h3><p>${esc(c.entry)}</p><h3>The tradeoff</h3><p>${esc(c.tradeoff)}</p></div></div><div class="career-tabs">${careerTabButton('course','Course',tab)}${careerTabButton('interview','Interview prep',tab)}${careerTabButton('employers','Companies',tab)}</div>${content}<div class="quiz"><span class="eyebrow">TRY THE WORK</span><h3>Practice assignment</h3><p>${esc(c.exercise)}</p></div>${sourceLinks(c.sources)}<button class="primary" data-save-career="${c.id}">${state.careerSaved.includes(c.id)?'✓ Saved — remove path':'Save this career path'}</button>`)
}
function portfolioPage(){return `<div class="panel"><span class="eyebrow">LEARN BY BUILDING</span><h2>Portfolio practice lab</h2><p>Choose percentages for a fictional portfolio. Learn how diversification and asset mix work; this is not a recommendation or model portfolio. Real investments can lose value.</p><div class="portfolio-grid">${portfolioItems.map((name,i)=>`<label>${name} (%)<input type="number" min="0" max="100" step="1" value="${portfolioValues[i]}" data-allocation="${i}"></label>`).join('')}</div><div class="button-row"><button class="secondary" id="portfolio-example">Load classroom example</button><label class="amount-label">Hypothetical starting amount ($)<input id="portfolio-amount" type="number" min="0" max="10000000" step="100" value="10000"></label></div><div id="portfolio-result" aria-live="polite"></div><div class="course-module"><h3>How to think through the mix</h3><p>Stocks represent ownership and can fluctuate substantially. Bonds are loans to issuers and have credit and interest-rate risk. Cash is liquid but can lose purchasing power to inflation. International holdings add exposure to other markets and currencies. Your goal, time horizon, liquidity needs and ability to bear loss affect the tradeoffs.</p><p>Rebalancing means adjusting a portfolio back toward chosen target percentages; it can involve transaction costs and taxes in taxable accounts. It does not ensure a profit.</p></div><p class="small-note">Classroom example is only for demonstrating arithmetic, not a suggested allocation. No entered values are sent to a server or saved.</p></div>`}
let portfolioValues=[0,0,0,0];
function updatePortfolio(){const out=$('#portfolio-result');if(!out)return;const total=portfolioValues.reduce((a,b)=>a+b,0),amount=Math.max(0,Number($('#portfolio-amount')?.value)||0);out.innerHTML=`<p class="${total===100?'form-status':'form-status error'}">Total: ${total}% ${total===100?'— percentages add up':'— adjust allocations to total 100%'}</p><div class="portfolio-breakdown">${portfolioItems.map((name,i)=>`<div class="allocation-row"><span>${name}</span><div class="allocation-track"><span style="width:${Math.max(0,Math.min(100,portfolioValues[i]))}%"></span></div><strong>${portfolioValues[i]}%</strong><small>${money(amount*portfolioValues[i]/100)}</small></div>`).join('')}</div>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.careerTab){renderCareerCourse($('#modal-body').querySelector('[data-save-career]')?.dataset.saveCareer,b.dataset.careerTab)}if(b.dataset.courseDone){const [id,i]=b.dataset.courseDone.split(':');state.courseDone[id]??=[];state.courseDone[id]=state.courseDone[id].includes(i)?state.courseDone[id].filter(x=>x!==i):[...state.courseDone[id],i];save();renderCareerCourse(id,'course')}if(b.id==='portfolio-example'){portfolioValues=[50,20,25,5];$$('[data-allocation]').forEach(x=>x.value=portfolioValues[Number(x.dataset.allocation)]);updatePortfolio()}});
document.addEventListener('change',e=>{if(e.target.dataset.allocation!==undefined){portfolioValues[Number(e.target.dataset.allocation)]=Math.min(100,Math.max(0,Number(e.target.value)||0));updatePortfolio()}});
document.addEventListener('input',e=>{if(e.target.id==='portfolio-amount')updatePortfolio()});

function marketGuide(){return `<section class="market-academy"><div class="section-head"><div><span class="eyebrow">MARKET PULSE CRASH COURSE</span><h2>How to read the graph</h2><p>Start with the instrument and time window; then read the change and ask what the measure leaves out.</p></div><button class="text-button" data-lesson="macro">Take the guided market lesson ${arrow}</button></div><div class="market-reading-grid"><article><span class="market-step">01</span><h3>Choose what you’re looking at</h3><p>Use the symbol selector above to switch among market indices and ETF proxies. An index is a calculation over a defined basket; an ETF is an investable fund with its own holdings, costs and tracking differences.</p></article><article><span class="market-step">02</span><h3>Read the vertical axis</h3><p>The vertical scale is the displayed index or fund price level in its quote units—not dollars you would earn. Index “points” are calculation units. A 1% move is easier to compare across indexes than a 100-point move.</p></article><article><span class="market-step">03</span><h3>Read the horizontal axis</h3><p>The horizontal scale is time. Select 1 day, 1 month, 3 months, 1 year, 5 years or all time. The line updates to that window; always say the date range when describing whether something rose or fell.</p></article><article><span class="market-step">04</span><h3>Interpret the line and shaded area</h3><p>The line connects quoted values at each plotted interval. The shaded area is visual fill below the line; it is not a second data series. Hover over a point to inspect the time and value. The chart uses an area display with the provider’s default scale.</p></article><article><span class="market-step">05</span><h3>Understand the interval</h3><p>The selected window pairs with an interval such as minutes, hours, days, weeks or months. A one-day/one-minute view shows noisy intraday changes; a five-year/weekly view compresses the path. Market closures and provider timestamps affect the latest point.</p></article><article><span class="market-step">06</span><h3>Read change and percent</h3><p>The header can show both the change in points or dollars and the percentage change for the selected comparison. Percent change is change divided by the starting value. Positive or negative color signals direction only; it does not predict the next move.</p></article></div><div class="market-note"><strong>What is not shown here:</strong> volume bars and moving-average overlays are turned off, so there are no volume columns or moving-average lines to interpret. This graph alone does not show every constituent, market breadth, dividends for every index version, or the reason prices moved. Data may be delayed; check the symbol, timestamp and source.</div><h3 class="subheading">The indexes in the selector</h3><div class="index-learning-grid"><article><strong>S&P 500 · SPX</strong><p>Large U.S. companies; float-adjusted market-cap weighting means larger constituents generally move the index more.</p></article><article><strong>Dow Jones Industrial Average · DJI</strong><p>30 large U.S. companies; price-weighted, so constituent share prices affect weight differently from market-cap weighting.</p></article><article><strong>Nasdaq-100 · NDX</strong><p>100 of the largest Nasdaq-listed nonfinancial companies; concentrated in large growth and technology-related firms.</p></article><article><strong>Nasdaq Composite · IXIC</strong><p>A broad index of Nasdaq-listed stocks; it is distinct from the narrower Nasdaq-100.</p></article><article><strong>Russell 2000 · RUT</strong><p>A benchmark for smaller U.S. companies; small firms can have different financing, liquidity and economic exposures.</p></article><article><strong>S&P MidCap 400 · SP400</strong><p>Tracks a segment of U.S. mid-sized companies under S&P index rules.</p></article><article><strong>S&P SmallCap 600 · SP600</strong><p>Tracks a segment of smaller U.S. companies selected under S&P methodology.</p></article><article><strong>NYSE Composite · NYA</strong><p>Measures stocks listed on the New York Stock Exchange; listing venue and company size are not the same thing.</p></article><article><strong>ETF proxies · SPY, QQQ, IWM</strong><p>Tradable funds designed to track related indexes. Fund prices and returns can differ from index values and include fund-level costs.</p></article></div><p class="account-source">Methodology references: <a href="https://www.spglobal.com/spdji/en/indices/equity/sp-500/" target="_blank" rel="noopener noreferrer">S&P 500 factsheet ↗</a> · <a href="https://indexes.nasdaqomx.com/docs/methodology_NDX.pdf" target="_blank" rel="noopener noreferrer">Nasdaq-100 methodology ↗</a> · <a href="https://www.spglobal.com/spdji/en/indices/equity/dow-jones-industrial-average/" target="_blank" rel="noopener noreferrer">Dow methodology overview ↗</a> · <a href="https://www.lseg.com/en/ftse-russell/indices/russell-us" target="_blank" rel="noopener noreferrer">FTSE Russell U.S. indexes ↗</a></p></section>`}
